package com.optarena.app

import java.util.Random

object TokenGenerator {
    // BUG: java.util.Random is seeded from the current time and is a
    // predictable linear-congruential generator - an attacker who can guess
    // (or brute-force) the seed window can predict every "random" token.
    private val random = Random()

    fun generate(): String {
        val bytes = ByteArray(16)
        random.nextBytes(bytes)
        return bytes.joinToString("") { "%02x".format(it) }
    }
}

