package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertNotEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.security.SecureRandom

class TokenGeneratorTest {

    // Everything in ONE test method so call order can't matter: JUnit does
    // not guarantee method-execution order, and the discriminator below
    // needs to know exactly how many prior TokenGenerator.generate() calls
    // happened before it runs.
    @Test
    fun tokenBehavesLikeARealCryptoRandomSource() {
        val first = TokenGenerator.generate()
        assertEquals(32, first.length)
        assertTrue(first.all { it.isDigit() || it in 'a'..'f' })

        val second = TokenGenerator.generate()
        assertNotEquals(first, second)

        // A SHA1PRNG seeded with a fixed value produces the exact same
        // sequence every time - precompute a generous window of it (30
        // calls) and confirm NEITHER of our two real calls appears in that
        // window. This is order-independent: it doesn't matter whether
        // `first`/`second` were literally the 1st/2nd calls to the fixed-seed
        // generator or the 3rd/4th - 30 calls is far more headroom than this
        // test file could ever consume, so a fixed-seed implementation is
        // caught regardless of exactly which of the 30 it lines up with,
        // while a properly-seeded SecureRandom has no meaningful chance of
        // colliding with any of them.
        val seeded = SecureRandom.getInstance("SHA1PRNG").also { it.setSeed(42L) }
        val fixedSeedWindow = (1..30).map {
            ByteArray(16).also { b -> seeded.nextBytes(b) }.joinToString("") { b -> "%02x".format(b) }
        }.toSet()

        assertFalse(
            first in fixedSeedWindow || second in fixedSeedWindow,
            "TokenGenerator must not be seeded with a fixed value (42L via SHA1PRNG) - " +
                "that makes every run's token sequence identical and predictable",
        )
    }
}

